import collections

class PathFinder:
    def __init__(self, start, goal):
        self.start = start
        self.goal = goal
        self.graph = {}  # Dictionary to store graph with nodes and connections
        self.open_set = collections.deque()  # For queue of nodes to be explored
        self.closed_set = set()  # For storing visited nodes

    def add_edge(self, start, end, weight=1):
        """Adds a connection (edge) between two nodes."""
        if start not in self.graph:
            self.graph[start] = {}
        self.graph[start][end] = weight

    def astar(self):
        """Finds the shortest path using A* search."""
        self.open_set.append(self.start)  # Add starting node to the open list
        f = {self.start: 0}  # Initialize f value for starting node as 0
        while self.open_set:
            current_node = next(iter(self.open_set))  # Get node with lowest f value
            if current_node == self.goal:
                self.path = self._build_path(current_node)  # Reconstruct path from goal
                return self.path  # Return the path
            self.closed_set.add(current_node)  # Mark current node as visited

            for neighbor in self.graph[current_node]:
                neighbor_node = neighbor  # get the neighbor of current_node
                if neighbor_node not in self.closed_set:
                    neighbor_cost = self.graph[current_node][neighbor_node] + f[current_node]  # Calculate total cost to reach neighbor
                    if neighbor_node not in self.open_set:
                        self.open_set.append(neighbor_node)
                        f[neighbor_node] = neighbor_cost
                    elif f[neighbor_node] > neighbor_cost:
                        f[neighbor_node] = neighbor_cost
                        self.open_set.remove(neighbor_node)
                        self.open_set.append(neighbor_node)  # Update f value if lower

        return None  # No path found


    def _build_path(self, node):
        """Reconstructs the path from the goal node."""
        path = [self.goal]
        while node != self.start:  # Traverse back towards the start
            for neighbor in self.graph[node]:
                if neighbor == node:
                    continue
                if neighbor in self.open_set:
                    path.append(neighbor)
                    node = neighbor
                    break

        return path[::-1]  # Reverse the path

    def visualize(self):
        """Visualize the graph if needed."""
        print("Graph:")
        for node in self.graph:
            print(f"Node: {node}, Connections: {self.graph[node]}")


# Example usage
