from collections import defaultdict

class Grid:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.grid = [[0 for _ in range(width)] for _ in range(height)]

    def set_cell(self, row, col, value):
        self.grid[row][col] = value

    def get_cell(self, row, col):
        return self.grid[row][col]

    def get_neighbors(self, row, col):
        neighbors = []
        for r, c in [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]:
            if 0 <= r < self.height and 0 <= c < self.width:
                neighbors.append((r, c))
        return neighbors

class AStar:
    def __init__(self, grid, start=(0, 0), goal=(width - 1, height - 1)):
        self.grid = grid
        self.start = start
        self.goal = goal
        self.open_set = { (start[0], start[1]) }
        self.closed_set = set()
        self.heuristic = lambda x, y: abs(x - goal[0]) + abs(y - goal[1])  # Manhattan distance

    def get_cost(self, start, goal):
        return abs(start[0] - goal[0]) + abs(start[1] - goal[1])

    def get_neighbors(self):
        neighbors = []
        for r, c in self.grid.get_neighbors(self.start[0], self.start[1]):
            neighbors.append(r, c)
        return neighbors

    def find_path(self):
        while self.open_set:
            current = self.open_set.pop(0)
            if current == self.goal:
                return self.backtrack(current)
            self.closed_set.add(current)
            for neighbor in self.get_neighbors():
                if neighbor not in self.closed_set:
                    g = self.get_cost(current, neighbor) + self.grid.get_cell(current[0], current[1])
                    h = self.heuristic(neighbor, self.goal)
                    if ((neighbor not in self.open_set or g < self.open_set[neighbor][0]) and h < self.open_set[neighbor][1]):
                        self.open_set.add((neighbor, g + h))
                        self.closed_set.add(neighbor)

    def backtrack(self, current):
        path = []
        while current:
            path.append(current)
            current = self.grid.get_cell(current[0], current[1])
        return path[::-1]

